import { calculateLineBisect } from './calculate-line-bisect.js';
import { XyPosition } from '../types/xy-position.js';

export const getHexagonLinesBisect = (hexagonVertexes: XyPosition[]) =>
  hexagonVertexes.map((point, index) => {
    const isLast = index === hexagonVertexes.length - 1;
    const nextPoint = isLast ? hexagonVertexes[0] : hexagonVertexes[index + 1];

    return calculateLineBisect(point, nextPoint);
  });
